INSERT INTO `github_jobs` (`id`, `external_id`, `title`, `company`, `salary_min`, `salary_max`, `salary_currency`, `employment_types`, `location_text`, `country`, `url`, `skills`, `work_model`, `seniority`, `posted_by`, `posted_at`, `description`, `collected_at`) VALUES
(1, 12310, 'Desenvolvedor(a) Rust Sênior - Sylision', NULL, NULL, NULL, 'BRL', NULL, NULL, NULL, 'https://github.com/backend-br/vagas/issues/12310', '[]', 'Remoto', 'Sênior', 'GiovaniPole0', '2026-07-05 14:24:08', '## Nossa empresa\n\nA [Sylision](https://sylision.com) é uma plataforma de recrutamento de tecnologia que atua no Brasil e em Portugal. Recrutamos para empresas parceiras e usamos IA para cruzar o seu CV com todas as vagas compatíveis do nosso banco em segundos — você se candidata uma única vez.\n\n## Descrição da vaga\n\nVaga de Desenvolvedor(a) Rust Sênior — 100% Remoto para atuar em projetos de empresas parceiras da Sylision. Área de Backend, nível Sênior.\n\nFaixa salarial: R$ 12.000 a R$ 22.000/mês, conforme experiência.\n\n## Local\n\n100% remoto, de qualquer lugar do Brasil ou de Portugal.\n\n## Requisitos\n\n**Obrigatórios:**\n- Experiência sólida com Rust compatível com o nível Sênior\n- Boas práticas de engenharia: versionamento, testes e code review\n\n**Desejáveis:**\n- Comunicação clara para trabalho remoto/distribuído\n- Inglês para leitura de documentação\n\n## Benefícios\n\n- Faixa salarial transparente (R$ 12.000–22.000/mês)\n- Benefícios variam conforme a empresa contratante (detalhados na conversa com o headhunter)\n\n## Contratação\n\nCLT ou PJ, conforme sua preferência e acordo com a empresa contratante.\n\n## Como se candidatar\n\nCandidate-se pela página da vaga: https://www.sylision.com/vagas/desenvolvedor-rust-senior-remoto\n\nBasta enviar o CV uma vez — a IA da Sylision considera seu perfil para esta e para todas as vagas compatíveis, inclusive as que abrirem depois.\n\n## Labels\n\n### Nível\n\n- Sênior\n\n### Regime\n\n- PJ\n- CLT\n\n### Alocação\n\n- Remoto\n', '2026-07-06 12:02:45'),
(2, 12309, '[Remoto] PHP/Python Software Engineer - F2AI', NULL, NULL, NULL, 'BRL', NULL, NULL, NULL, 'https://github.com/backend-br/vagas/issues/12309', '[\"PHP\",\"Python\",\"Git\",\"Docker\"]', 'Remoto', 'Sênior', 'huberemanuel', '2026-07-03 21:01:50', '<!-- Por favor, poste apenas vagas para backend. -->\n\n## Sobre a F2AI\n\nSomos uma startup que desenvolve uma plataforma enterprise para inferência de modelos de IA generativa em infraestrutura local. Nosso foco é permitir que organizações rodem LLMs em seus próprios ambientes, com controle total sobre dados e recursos.\n\nInfos sobre o produto: https://f2ai.com.br/\n\n## Descrição da vaga\n\nDesenvolver e manter aplicações full-stack com Laravel e Python/FastAPI\nIntegrar o control plane da plataforma com clusters Kubernetes via API\nConstruir interfaces para gerenciamento de deployments de modelos de IA\nTrabalhar com containerização, APIs REST e arquiteturas de microsserviços\nColaborar na evolução de features como fine-tuning, RAG e bibliotecas de prompts\n\n## Local\n\nTrabalho remoto, escritório em São Paulo, capital.\n\n## Requisitos\n\nFundamentos sólidos:\n\n    Estruturas de dados e algoritmos\n    Sistemas operacionais e redes\n    Bancos de dados relacionais e modelagem de dados\n\nExperiência prática:\n\n    PHP (Laravel) ou Python (FastAPI/Flask)\n    Desenvolvimento full-stack\n    Docker e containerização\n    APIs REST e integrações entre sistemas\n    Git e práticas de versionamento\n\nPerfil:\n\n    Autonomia e capacidade de resolver problemas com pouca orientação\n    Comunicação clara em português\n\nDiferenciais:\n\n    Kubernetes\n    Projetos envolvendo IA/ML\n    Bancos vetoriais ou arquiteturas RAG\n    Infraestrutura on-premises\n\n## Benefícios\n\n* Trabalho 100% remoto\n* Atuação direta com tecnologias de IA generativa em ambiente enterprise\n* Ambiente de startup com autonomia e impacto\n* Crescimento técnico em um domínio em expansão\n\n## Contratação\n\nPJ\n\n## Como se candidatar\n\nEnviar currículo para emanuel.huber@f2ai.com.br\n\n## Labels\n\n<!-- Retire os labels que não fazem sentido à vaga. -->\n\n### Nível\n\n- Sênior\n\n\n### Regime\n\n- PJ\n\n### Alocação\n\n- Remoto\n\n', '2026-08-26 11:20:46'),
(3, 12308, 'Desenvolvedor(a) Ruby on Rails Sênior - Sylision', NULL, NULL, NULL, 'BRL', NULL, NULL, NULL, 'https://github.com/backend-br/vagas/issues/12308', '[\"Ruby\"]', 'Remoto', 'Sênior', 'GiovaniPole0', '2026-07-03 13:10:02', '## Nossa empresa\r\n\r\nA [Sylision](https://sylision.com) é uma plataforma de recrutamento de tecnologia que atua no Brasil e em Portugal. Recrutamos para empresas parceiras e usamos IA para cruzar o seu CV com todas as vagas compatíveis do nosso banco em segundos — você se candidata uma única vez.\r\n\r\n## Descrição da vaga\r\n\r\nVaga de Desenvolvedor(a) Ruby on Rails Sênior — 100% Remoto para atuar em projetos de empresas parceiras da Sylision. Área de Backend, nível Sênior.\r\n\r\nFaixa salarial: R$ 12.000 a R$ 22.000/mês, conforme experiência.\r\n\r\n## Local\r\n\r\n100% remoto, de qualquer lugar do Brasil ou de Portugal.\r\n\r\n## Requisitos\r\n\r\n**Obrigatórios:**\r\n- Experiência sólida com Ruby on Rails compatível com o nível Sênior\r\n- Boas práticas de engenharia: versionamento, testes e code review\r\n\r\n**Desejáveis:**\r\n- Comunicação clara para trabalho remoto/distribuído\r\n- Inglês para leitura de documentação\r\n\r\n## Benefícios\r\n\r\n- Faixa salarial transparente (R$ 12.000–22.000/mês)\r\n- Benefícios variam conforme a empresa contratante (detalhados na conversa com o headhunter)\r\n\r\n## Contratação\r\n\r\nCLT ou PJ, conforme sua preferência e acordo com a empresa contratante.\r\n\r\n## Como se candidatar\r\n\r\nCandidate-se pela página da vaga: https://www.sylision.com/vagas/desenvolvedor-ruby-on-rails-senior-remoto\r\n\r\nBasta enviar o CV uma vez — a IA da Sylision considera seu perfil para esta e para todas as vagas compatíveis, inclusive as que abrirem depois.\r\n\r\n## Labels\r\n\r\n### Nível\r\n\r\n- Sênior\r\n\r\n### Regime\r\n\r\n- PJ\r\n- CLT\r\n\r\n### Alocação\r\n\r\n- Remoto\r\n', '2026-07-06 12:02:45'),
(4, 12307, 'Desenvolvedor(a) Python Sênior - Sylision', NULL, NULL, NULL, 'BRL', NULL, NULL, NULL, 'https://github.com/backend-br/vagas/issues/12307', '[\"Python\"]', 'Remoto', 'Sênior', 'GiovaniPole0', '2026-07-03 13:08:51', '## Nossa empresa\r\n\r\nA [Sylision](https://sylision.com) é uma plataforma de recrutamento de tecnologia que atua no Brasil e em Portugal. Recrutamos para empresas parceiras e usamos IA para cruzar o seu CV com todas as vagas compatíveis do nosso banco em segundos — você se candidata uma única vez.\r\n\r\n## Descrição da vaga\r\n\r\nVaga de Desenvolvedor(a) Python Sênior — 100% Remoto para atuar em projetos de empresas parceiras da Sylision. Área de Backend, nível Sênior.\r\n\r\nFaixa salarial: R$ 12.000 a R$ 22.000/mês, conforme experiência.\r\n\r\n## Local\r\n\r\n100% remoto, de qualquer lugar do Brasil ou de Portugal.\r\n\r\n## Requisitos\r\n\r\n**Obrigatórios:**\r\n- Experiência sólida com Python compatível com o nível Sênior\r\n- Boas práticas de engenharia: versionamento, testes e code review\r\n\r\n**Desejáveis:**\r\n- Comunicação clara para trabalho remoto/distribuído\r\n- Inglês para leitura de documentação\r\n\r\n## Benefícios\r\n\r\n- Faixa salarial transparente (R$ 12.000–22.000/mês)\r\n- Benefícios variam conforme a empresa contratante (detalhados na conversa com o headhunter)\r\n\r\n## Contratação\r\n\r\nCLT ou PJ, conforme sua preferência e acordo com a empresa contratante.\r\n\r\n## Como se candidatar\r\n\r\nCandidate-se pela página da vaga: https://www.sylision.com/vagas/desenvolvedor-python-senior-remoto\r\n\r\nBasta enviar o CV uma vez — a IA da Sylision considera seu perfil para esta e para todas as vagas compatíveis, inclusive as que abrirem depois.\r\n\r\n## Labels\r\n\r\n### Nível\r\n\r\n- Sênior\r\n\r\n### Regime\r\n\r\n- PJ\r\n- CLT\r\n\r\n### Alocação\r\n\r\n- Remoto\r\n', '2026-07-06 12:02:45'),
